// Replace the placeholders below with your own values. Never commit real keys.
const GOVEE_API_KEY = "your-govee-api-key";
const GOVEE_DEVICE_ID = "your-device-id"; // the 'device' value from Govee's device list (see README step 1)
const GOVEE_SKU = "H5179";

if (GOVEE_API_KEY.startsWith("your-") || GOVEE_DEVICE_ID.startsWith("your-")) {
    node.error("Fill in your Govee API key and device ID in 'Build Govee request'.", msg);
    return null;
}
msg.method = "POST";
msg.url = "https://openapi.api.govee.com/router/api/v1/device/state";
msg.headers = {
    "Content-Type": "application/json",
    "Govee-API-Key": GOVEE_API_KEY
};
msg.payload = {
    requestId: "nodered-h5179",
    payload: { sku: GOVEE_SKU, device: GOVEE_DEVICE_ID }
};
return msg;

// Extract temperature/humidity from the Govee response and prepare two REST publish calls to IoT Open (Lynx).

// Unit that Govee reports the temperature in. Set to "F" if your values look like Fahrenheit.
// IoT Open always receives Celsius.
const GOVEE_TEMP_UNIT = "C";

if (msg.statusCode < 200 || msg.statusCode >= 300) {
    node.error("Govee HTTP error: " + msg.statusCode, msg);
    return null;
}
const response = msg.payload;
if (!response || Number(response.code) !== 200 || !response.payload || !Array.isArray(response.payload.capabilities)) {
    node.error("Unexpected Govee response. Check API key, SKU and device ID.", msg);
    return null;
}
const caps = response.payload.capabilities;
function getValue(instance) {
    const item = caps.find(c => c.instance === instance && c.state && c.state.value !== undefined && c.state.value !== null);
    return item ? Number(item.state.value) : NaN;
}
const rawTemperature = getValue("sensorTemperature");
const humidity = getValue("sensorHumidity");
if (!Number.isFinite(rawTemperature) || !Number.isFinite(humidity)) {
    node.error("sensorTemperature/sensorHumidity not found in the Govee response.", msg);
    return null;
}
if (GOVEE_TEMP_UNIT === "C" && rawTemperature > 45) {
    node.warn("Temperature " + rawTemperature + " looks like Fahrenheit. Set GOVEE_TEMP_UNIT to F if so.");
}
const temperature = GOVEE_TEMP_UNIT === "F" ? Math.round((rawTemperature - 32) * 5 / 9 * 10) / 10 : rawTemperature;
node.status({ text: temperature + " °C / " + humidity + " %RH" });

// --- IoT Open (Lynx) settings. Replace the placeholders. Never commit real keys. ---
const IOTOPEN_API_KEY = "your-iot-open-api-key";
const IOTOPEN_INSTALLATION_ID = "your-installation-id";
// These must match 'topic_read' on the functions in IoT Open.
// The installation ID is added as a prefix automatically by the publish API.
const TOPIC_TEMPERATURE = "obj/govee/temperatur";
const TOPIC_HUMIDITY = "obj/govee/luftfuktighet";

if (IOTOPEN_API_KEY.startsWith("your-") || IOTOPEN_INSTALLATION_ID.startsWith("your-")) {
    node.warn("Govee data was read, but the IoT Open settings are not filled in yet.");
    return null;
}
const baseUrl = "https://lynx.iotopen.se/api/v2/mqtt/publish/" + encodeURIComponent(IOTOPEN_INSTALLATION_ID);
function publish(topic, value, unit) {
    return {
        method: "POST",
        url: baseUrl,
        headers: {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "X-API-Key": IOTOPEN_API_KEY
        },
        payload: {
            topic: topic,
            payload: { value: value, msg: "source=Govee H5179; unit=" + unit }
        }
    };
}
return [publish(TOPIC_TEMPERATURE, temperature, "C"), publish(TOPIC_HUMIDITY, humidity, "%RH")];
